using System.Diagnostics;
using System.Reflection;
using System.Security.Cryptography;
using System.Text.Json;
using CardGame.Core;

var normalDirectory = Path.GetFullPath(args[0]);
var outputPath = Path.GetFullPath(args[1]);
var sourcePath = Path.Combine(Path.GetDirectoryName(outputPath)!, "borrowed-operation-source-hashes.json");
string Hash(string path) => Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path)));
var dllPaths = new[] { "CardGame.Core.dll", "CardGame.Content.Standard.dll", "CardGame.Core.Tests.dll" }
    .Select(name => Path.Combine(normalDirectory, name)).ToArray();
var dllBefore = dllPaths.Select(path => new { path, sha256 = Hash(path) }).ToArray();
var loadedAssemblies = new[] { typeof(GameEngine).Assembly, typeof(CardGame.Content.Standard.StandardContentPackage).Assembly }
    .Select(item => new { assembly = item.GetName().Name, location = item.Location, sha256 = Hash(item.Location),
        normalSha256 = Hash(Path.Combine(normalDirectory, item.GetName().Name + ".dll")) }).ToArray();
if (loadedAssemblies.Any(item => item.sha256 != item.normalSha256)) throw new InvalidOperationException("Loaded runtime differs from normal output.");
var assembly = Assembly.LoadFrom(Path.Combine(normalDirectory, "CardGame.Core.Tests.dll"));
var rows = new List<object>();
var normalRows = new List<object>();
foreach (var (name, copied, originalType, originalMethod) in new (string, Action, string, string)[] {
    ("WuXian complete four branches", WuXianOperationDiagnostic.BorrowedSwordPairsActualUseAndReplay, "Fame2017WuXianChecks", "BorrowedSwordPairsActualUseAndReplay"),
    ("PublicPile complete scenario", PublicPileOperationDiagnostic.StoreExchangeDistributionAndReplay, "Fame2017PublicPileChecks", "StoreExchangeDistributionAndReplay") })
{
    if (args.Length > 2 && args[2] == "native-only") break;
    var original = assembly.GetType(originalType)!.GetMethod(originalMethod)!.CreateDelegate<Action>();
    for (var iteration = 0; iteration < 8; iteration++)
    {
        GC.Collect(); GC.WaitForPendingFinalizers(); GC.Collect();
        BorrowedProbeMeter.Reset();
        var bytes = GC.GetTotalAllocatedBytes(true); var started = Stopwatch.GetTimestamp();
        copied();
        var elapsed = BorrowedProbeMeter.ToMs(Stopwatch.GetTimestamp() - started);
        rows.Add(new { name, iteration, ms = elapsed, bytes = GC.GetTotalAllocatedBytes(true) - bytes, detail = BorrowedProbeMeter.Report() });
        Console.WriteLine($"DIAGNOSTIC {name} [{iteration}]: {elapsed:F3} ms");
        GC.Collect(); GC.WaitForPendingFinalizers(); GC.Collect();
        bytes = GC.GetTotalAllocatedBytes(true); started = Stopwatch.GetTimestamp();
        original();
        elapsed = BorrowedProbeMeter.ToMs(Stopwatch.GetTimestamp() - started);
        normalRows.Add(new { name, iteration, ms = elapsed, bytes = GC.GetTotalAllocatedBytes(true) - bytes });
        Console.WriteLine($"NORMAL {name} [{iteration}]: {elapsed:F3} ms");
    }
}

// Fixture discovery, checkpoint JSON, fresh restores, commands and choices are all outside operation timing.
BorrowedProbeMeter.Enabled = false;
var registry = BorrowedScenarioOperationDiagnostic.CreateFixtureRegistry();
var boundary = BorrowedScenarioOperationDiagnostic.FindHumanOwnerResponse();
var checkpoint = GameCheckpointJson.Deserialize(GameCheckpointJson.Serialize(boundary.CreateCheckpoint()));
var fixtureRows = new List<object>();
foreach (var branch in new[] { "borrowed-sword-give-weapon", "borrowed-sword-slash" })
{
    for (var iteration = 0; iteration < 8; iteration++)
    {
        var game = GameReplay.Restore(checkpoint, registry);
        var decision = game.PendingDecision!;
        var choice = decision.Choices.First(c => c.Parameters.GetValueOrDefault("response") == branch);
        var parent = game.ResolutionStack.OfType<CardUseFrame>().Single(f => f.CardKind == CardKind.BorrowedSword);
        var command = new AnswerPromptCommand(decision.PlayerSeat, decision.PromptId, choice.Id, game.Revision);
        var beforeEvents = game.Events.Count; var beforeCommands = game.AcceptedCommands.Count;
        GC.Collect(); GC.WaitForPendingFinalizers(); GC.Collect();
        BorrowedProbeMeter.Reset(); BorrowedProbeMeter.Enabled = true;
        var bytes = GC.GetTotalAllocatedBytes(true); var started = Stopwatch.GetTimestamp();
        var accepted = BorrowedProbeMeter.Submit(game, command);
        if (!accepted.Accepted) throw new InvalidOperationException(accepted.Error?.Message);
        var submitElapsed = BorrowedProbeMeter.ToMs(Stopwatch.GetTimestamp() - started);
        for (var step = 0; HasParent(game, parent.Id); step++)
        {
            if (step == 128) throw new InvalidOperationException("Parent failed to complete.");
            BorrowedScenarioOperationDiagnostic.Step(game);
        }
        var elapsed = BorrowedProbeMeter.ToMs(Stopwatch.GetTimestamp() - started);
        var allocated = GC.GetTotalAllocatedBytes(true) - bytes;
        BorrowedProbeMeter.Enabled = false;
        var payloads = game.Events.Skip(beforeEvents).Select(e => e.Payload).ToArray();
        var resolved = payloads.OfType<BorrowedSwordResolvedEvent>().Single(e => e.ResolutionId == parent.Id);
        if (resolved.UsedSlash != (branch == "borrowed-sword-slash")) throw new InvalidOperationException("Wrong actual branch outcome.");
        fixtureRows.Add(new { branch, iteration, sourceSeed = boundary.Seed, initialMeasuredSubmitMs = submitElapsed,
            responseToParentCompleteMs = elapsed, allocatedBytes = allocated, directCommands = game.AcceptedCommands.Count - beforeCommands,
            childSlashUses = payloads.OfType<CardUseDeclaredEvent>().Count(e => e.CardKind is CardKind.Slash or CardKind.FireSlash or CardKind.ThunderSlash),
            result = resolved, detail = BorrowedProbeMeter.Report() });
        Console.WriteLine($"NATIVE {branch} [{iteration}]: Submit={submitElapsed:F3} ms, complete={elapsed:F3} ms");
    }
}
var dllAfter = dllPaths.Select(path => new { path, sha256 = Hash(path) }).ToArray();
if (!dllBefore.Select(x => x.sha256).SequenceEqual(dllAfter.Select(x => x.sha256))) throw new InvalidOperationException("Normal DLLs changed during diagnostic.");
using var sourceDocument = JsonDocument.Parse(File.ReadAllText(sourcePath));
foreach (var row in sourceDocument.RootElement.EnumerateArray())
    if (Hash(row.GetProperty("path").GetString()!) != row.GetProperty("sha256").GetString()) throw new InvalidOperationException("Original fixture source changed during diagnostic.");
var resultObject = new {
    method = "Copied diagnostic methods retain all four Wu branches, every assertion, 12/17 independent restores and four-view comparisons. Decorated diagnostic timings are attribution only; Normal rows invoke original unchanged compiled methods. Native operation starts after fresh restore, fixture discovery/JSON/GC excluded, native AI and ordinary prompt/advance included. Iteration 0 is first measured use, not wholly cold process. Warm summary excludes iteration 0. No Core instrumentation or DLL swapping.",
    nativeOnly = args.Length > 2 && args[2] == "native-only",
    normalDirectory, rulesVersion = typeof(GameCheckpoint).GetField("CurrentRulesVersion")!.GetRawConstantValue(),
    tieredCompilation = Environment.GetEnvironmentVariable("DOTNET_TieredCompilation") ?? "default", loadedAssemblies,
    dllBefore, dllAfter, sourceHashes = sourceDocument.RootElement.Clone(), diagnosticRows = rows,
    normalCompleteRows = normalRows, nativeOperationRows = fixtureRows
};
File.WriteAllText(outputPath, JsonSerializer.Serialize(resultObject, new JsonSerializerOptions { WriteIndented = true }));
Console.WriteLine("All copied assertions passed; normal DLL and original source hashes unchanged.");

static bool HasParent(GameEngine game, long parentId)
{
    var frames = game.ResolutionStack;
    for (var i = 0; i < frames.Count; i++) if (frames[i] is CardUseFrame use && use.Id == parentId) return true;
    return false;
}

using System.Diagnostics;
using System.Text.Json;
using CardGame.Core;

internal static class BorrowedProbeMeter
{
    private static readonly Dictionary<string, Bucket> Buckets = new(StringComparer.Ordinal);
    private static readonly Stack<Scope> Open = new();
    internal static readonly List<object> ActualUses = [];
    internal static long ReplayedCommands;
    private static ActualUse? CurrentActual;
    internal static bool Enabled = true;

    internal sealed class Bucket
    {
        internal readonly List<double> Samples = [];
        internal double SelfMs;
        internal long Bytes, SelfBytes;
    }
    internal sealed class Scope : IDisposable
    {
        private readonly string _name;
        private readonly long _start, _bytes;
        private readonly bool _enabled;
        private long _childTicks, _childBytes;
        internal Scope(string name)
        {
            _name = name; _enabled = Enabled;
            if (!_enabled) return;
            _start = Stopwatch.GetTimestamp(); _bytes = GC.GetAllocatedBytesForCurrentThread(); Open.Push(this);
        }
        public void Dispose()
        {
            if (!_enabled) return;
            var ticks = Stopwatch.GetTimestamp() - _start;
            var bytes = GC.GetAllocatedBytesForCurrentThread() - _bytes;
            if (!ReferenceEquals(Open.Pop(), this)) throw new InvalidOperationException("Probe scopes must close in order.");
            if (Open.TryPeek(out var parent)) { parent._childTicks += ticks; parent._childBytes += bytes; }
            if (!Buckets.TryGetValue(_name, out var bucket)) Buckets[_name] = bucket = new();
            bucket.Samples.Add(ToMs(ticks)); bucket.SelfMs += ToMs(ticks - _childTicks);
            bucket.Bytes += bytes; bucket.SelfBytes += bytes - _childBytes;
        }
    }
    internal static Scope Begin(string name) => new(name);
    internal static void Reset()
    {
        if (Open.Count != 0) throw new InvalidOperationException("Open measurement scope at reset.");
        Buckets.Clear(); ActualUses.Clear(); ReplayedCommands = 0; CurrentActual = null;
    }
    internal static double ToMs(long ticks) => ticks * 1000.0 / Stopwatch.Frequency;
    internal static object Summarize(IEnumerable<double> values)
    {
        var sorted = values.Order().ToArray();
        return new { Count = sorted.Length, TotalMs = sorted.Sum(), MedianMs = sorted.Length == 0 ? 0 : sorted[sorted.Length / 2],
            P95Ms = sorted.Length == 0 ? 0 : sorted[(int)Math.Ceiling(sorted.Length * .95) - 1], MaxMs = sorted.LastOrDefault() };
    }
    internal static object Report() => new
    {
        Buckets = Buckets.Select(p => new { Name = p.Key, Summary = Summarize(p.Value.Samples),
            SamplesMs = p.Key == "DirectSubmit" ? p.Value.Samples.ToArray() : null,
            p.Value.SelfMs, p.Value.Bytes, p.Value.SelfBytes }).ToArray(),
        ReplayedCommands, ActualUses = ActualUses.ToArray()
    };
    internal static CommandResult Submit(GameEngine game, GameCommand command)
    {
        using var scope = Begin("DirectSubmit");
        var started = Stopwatch.GetTimestamp();
        var result = game.Submit(command);
        CurrentActual?.RecordCommand(command.GetType().Name, ToMs(Stopwatch.GetTimestamp() - started));
        return result;
    }
    internal static GameSnapshot Snapshot(GameEngine game, int viewerSeat, bool revealAll = false)
    { using var scope = Begin("ExplicitSnapshot"); return game.CreateSnapshot(viewerSeat, revealAll); }
    internal static IReadOnlyList<LegalAction> Actions(GameEngine game)
    { using var scope = Begin("ExplicitActions"); return game.GetHumanLegalActions(); }
    internal static string SnapshotSerialize(GameSnapshot snapshot)
    { using var scope = Begin("SnapshotJson"); return SnapshotJson.Serialize(snapshot); }
    internal static string Json<T>(T value)
    { using var scope = Begin("OtherObservationJson"); return JsonSerializer.Serialize(value); }
    internal static string Json(object? value, Type inputType)
    { using var scope = Begin("OtherObservationJson"); return JsonSerializer.Serialize(value, inputType); }
    internal static string CommandsEncode(IEnumerable<GameCommand> commands)
    { using var scope = Begin("CommandJsonEncode"); return CommandJson.Serialize(commands); }
    internal static IReadOnlyList<GameCommand> CommandsDecode(string json)
    { using var scope = Begin("CommandJsonDecode"); return CommandJson.Deserialize(json); }
    internal static GameCheckpoint Checkpoint(GameEngine game)
    { using var scope = Begin("CheckpointCapture"); return game.CreateCheckpoint(); }
    internal static string CheckpointEncode(GameCheckpoint checkpoint)
    { using var scope = Begin("CheckpointJsonEncode"); return GameCheckpointJson.Serialize(checkpoint); }
    internal static GameCheckpoint CheckpointDecode(string json)
    { using var scope = Begin("CheckpointJsonDecode"); return GameCheckpointJson.Deserialize(json); }
    internal static GameEngine Restore(GameCheckpoint checkpoint, ContentRegistry registry)
    { using var scope = Begin("ColdRestore"); ReplayedCommands += checkpoint.Commands.Count; return GameReplay.Restore(checkpoint, registry); }

    internal sealed class ActualUse
    {
        private readonly long _started = Stopwatch.GetTimestamp();
        private readonly long _beforeCommands, _beforeEvents, _beforeMoves;
        private long _activeStart = Stopwatch.GetTimestamp(), _activeTicks;
        private bool _active = true;
        private readonly List<double> _commands = [];
        private readonly List<object> _commandDetails = [];
        private string _stage = "PlayCard through native weapon-owner responses";
        private readonly bool _converted;
        private readonly int _count;
        internal ActualUse(GameEngine game, bool converted, int count)
        {
            _beforeCommands = game.AcceptedCommands.Count; _beforeEvents = game.Events.Count; _beforeMoves = game.CardMovements.Count;
            _converted = converted; _count = count;
        }
        internal void RecordCommand(string commandType, double ms)
        { if (_active) { _commands.Add(ms); _commandDetails.Add(new { commandType, stage = _stage, ms }); } }
        internal void Pause() { if (_active) { _activeTicks += Stopwatch.GetTimestamp() - _activeStart; _active = false; } }
        internal void Resume() { _stage = "fixture completion answer through next Play prompt"; _activeStart = Stopwatch.GetTimestamp(); _active = true; }
        internal void Finish(GameEngine game, long parentId)
        {
            Pause(); var end = Stopwatch.GetTimestamp(); CurrentActual = null;
            var newEvents = game.Events.Skip((int)_beforeEvents).Select(e => e.Payload).ToArray();
            var results = newEvents.OfType<BorrowedSwordResolvedEvent>().Where(e => e.ResolutionId == parentId).ToArray();
            ActualUses.Add(new { Converted = _converted, TargetSeatCount = _count, PairCount = _count / 2,
                InclusiveWallMs = ToMs(end - _started), ActualExecutionMs = ToMs(_activeTicks),
                DirectCommands = game.AcceptedCommands.Count - _beforeCommands,
                ActiveCommandLatency = Summarize(_commands), ActiveCommandSamplesMs = _commands.ToArray(), ActiveCommandDetails = _commandDetails.ToArray(),
                EventCount = newEvents.Length, MovementCount = game.CardMovements.Count - _beforeMoves,
                ChildSlashUses = newEvents.OfType<CardUseDeclaredEvent>().Count(e => e.CardKind is CardKind.Slash or CardKind.FireSlash or CardKind.ThunderSlash),
                UsedSlashPairs = results.Count(e => e.UsedSlash), WeaponTransfers = results.Count(e => e.TransferredWeaponCardId is not null),
                ParentCompleted = !game.ResolutionStack.OfType<CardUseFrame>().Any(e => e.Id == parentId) });
        }
    }
    internal static ActualUse BeginActual(GameEngine game, bool converted, int count) => CurrentActual = new(game, converted, count);
}

using System.Reflection;
using System.Security.Cryptography;
using System.Text.Json;
using CardGame.Core;
string Hash(string p) => Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(p)));
var normal = Path.Combine(args[0], "CardGame.Core.dll");
var source = @"C:\Users\17917\Desktop\Card\tests\CardGame.Core.Tests\CardResponseCompletionCostChecks.cs";
var before = Hash(normal); var sourceBefore = Hash(source);
var loaded = typeof(GameEngine).Assembly.Location; var loadedHash = Hash(loaded);
if (loadedHash != before) throw new InvalidOperationException("Loaded Core differs from normal output.");
var method = typeof(CardResponseCompletionCostChecks).GetMethod("VerifyFactionDefenseDodgeHealthDyingReturn", BindingFlags.NonPublic|BindingFlags.Static)!;
bool rejected = false, expectedRed = false; string? error = null, stack = null;
try { method.Invoke(null, null); }
catch (TargetInvocationException e) {
 var inner = e.InnerException!;
 rejected = true; error = inner.ToString(); stack = inner.StackTrace;
 expectedRed = inner.Message == "A native response health child lost its exact paid return." && (stack?.Contains("AssertCoreInvariants", StringComparison.Ordinal) == true);
}
var after = Hash(normal); var sourceAfter = Hash(source);
if (before != after || sourceBefore != sourceAfter) throw new InvalidOperationException("Normal output or source changed during RED.");
var output = new {
 measuredAt=DateTimeOffset.Now, rulesVersion=typeof(GameCheckpoint).GetField("CurrentRulesVersion")!.GetRawConstantValue(),
 method=method.Name, expectedRed, rejected, error, stack, normalCore=normal, before, after,
 loadedCore=loaded, loadedHash, source, sourceBefore, sourceAfter,
 description="Tests-only real faction Defense supplied equipment Dodge: actual Silver Lion payment reaches normal command invariant. The normal Core is unchanged."
};
File.WriteAllText(args[1],JsonSerializer.Serialize(output,new JsonSerializerOptions{WriteIndented=true}));
Console.WriteLine($"RED expected={expectedRed}; rejected={rejected}; error={error}");
Environment.ExitCode = expectedRed ? 0 : 2;
